
import { useContext, useEffect } from "react";

//Context and tools
import { userContext } from "../../UserProvider";
import { useParams, useSearchParams } from "react-router-dom";
import useGoTo from "../../hooks/useGoTo";

// Styles and components
import bg from "../../assets/images/background-postfeed-light.png";
import BackgroundWrapper from "../../components/base-components/BackgroundWrapper";
import NavigationBar from "../../components/base-components/NavigationBar/NavigationBar";
import SideMenu from "../../components/SideMenu/SideMenu";
import PostFeed from "../../components/PostFeed/PostFeed";
import ChatRoom from "../../components/ChatRoom/ChatRoom";
import "./Groups.css";
import ChatList from "../../components/ChatList/ChatList";

export default function GroupsFeed(){
    const {groupId} = useParams();
    const [searchParams] = useSearchParams();
    const {user} = useContext(userContext);
    const chatId = searchParams.get("cid");
    const goTo = useGoTo();

    console.log("chatId in groups feed: ", chatId);

    useEffect(()=>{
            if (!user) {
            goTo("/");
        }
    },[user,goTo]);

    return(
    <>
          <BackgroundWrapper
            title="Group Feed"
            backgroundImage = {bg}
            backgroundPosition = "top center"
            backgroundRepeat="repeat-y"
            backgroundAttachment = "scroll"
            >

            <div className="groups">
                <NavigationBar/>
                <div className="page-container">
                    <SideMenu />
                    <PostFeed className="center-container" type="group"/>
                    {chatId
                    ? (<div className="groups-feed-chat-container docked-container">
                            <ChatRoom miniView={true} chatId={chatId} />
                      </div>) 
                    : <ChatList/>}
                </div>
            </div>
        </BackgroundWrapper>
    </>
    );
}